document.addEventListener('DOMContentLoaded', () => {
const mobileToggle = document.getElementById('mobileToggle');
const navMenu = document.getElementById('navMenu');
function closeMobileNav() {
if (!navMenu || !navMenu.classList.contains('open')) return;
navMenu.classList.remove('open');
if (mobileToggle) {
mobileToggle.setAttribute('aria-expanded', 'false');
const icon = mobileToggle.querySelector('i');
if (icon) {
icon.classList.remove('fa-xmark', 'fa-times');
icon.classList.add('fa-bars');
}
}
}
function openMobileNav() {
if (!navMenu) return;
navMenu.classList.add('open');
if (mobileToggle) {
mobileToggle.setAttribute('aria-expanded', 'true');
const icon = mobileToggle.querySelector('i');
if (icon) {
icon.classList.remove('fa-bars');
icon.classList.add('fa-xmark');
}
}
}
if (mobileToggle && navMenu) {
mobileToggle.addEventListener('click', (e) => {
e.stopPropagation();
if (navMenu.classList.contains('open')) {
closeMobileNav();
} else {
openMobileNav();
}
});
navMenu.querySelectorAll('a, button').forEach(item => {
item.addEventListener('click', () => {
closeMobileNav();
});
});
document.addEventListener('click', (e) => {
if (!navMenu.contains(e.target) && !mobileToggle.contains(e.target)) {
closeMobileNav();
}
});
document.addEventListener('keydown', (e) => {
if (e.key === 'Escape') {
closeMobileNav();
document.querySelectorAll('.modal-backdrop.open').forEach(m => m.classList.remove('open'));
}
});
window.addEventListener('resize', () => {
if (window.innerWidth > 1024) {
closeMobileNav();
}
});
}
const header = document.querySelector('.main-header');
let isTicking = false;
window.addEventListener('scroll', () => {
if (!isTicking) {
window.requestAnimationFrame(() => {
if (window.scrollY > 50) {
header?.classList.add('scrolled');
} else {
header?.classList.remove('scrolled');
}
isTicking = false;
});
isTicking = true;
}
}, { passive: true });
const filterBtns = document.querySelectorAll('.filter-btn');
const fabricCards = document.querySelectorAll('.fabric-card');
filterBtns.forEach(btn => {
btn.addEventListener('click', () => {
filterBtns.forEach(b => b.classList.remove('active'));
btn.classList.add('active');
const filter = btn.getAttribute('data-filter');
fabricCards.forEach(card => {
const category = card.getAttribute('data-category');
if (filter === 'all' || category === filter || (filter === 'blends' && (category === 'tc' || category === 'cvc' || category === 'tr'))) {
card.style.display = 'flex';
card.style.animation = 'fadeIn 0.35s ease';
} else {
card.style.display = 'none';
}
});
});
});
const tabBtns = document.querySelectorAll('.facility-tab-btn');
const tabPanes = document.querySelectorAll('.facility-pane');
tabBtns.forEach(btn => {
btn.addEventListener('click', () => {
const target = btn.getAttribute('data-tab');
tabBtns.forEach(b => b.classList.remove('active'));
tabPanes.forEach(p => p.classList.remove('active'));
btn.classList.add('active');
const activePane = document.getElementById(target);
if (activePane) {
activePane.classList.add('active');
}
});
});
const locBtns = document.querySelectorAll('.loc-tab-btn');
const locHeadOffice = document.getElementById('locHeadOffice');
const locWeaving = document.getElementById('locWeaving');
const locDyeing = document.getElementById('locDyeing');
locBtns.forEach(btn => {
btn.addEventListener('click', () => {
locBtns.forEach(b => b.classList.remove('active'));
btn.classList.add('active');
const loc = btn.getAttribute('data-loc');
if (locHeadOffice) locHeadOffice.style.display = (loc === 'office') ? 'block' : 'none';
if (locWeaving) locWeaving.style.display = (loc === 'weaving') ? 'block' : 'none';
if (locDyeing) locDyeing.style.display = (loc === 'dyeing') ? 'block' : 'none';
});
});
const rfqModal = document.getElementById('rfqModal');
const rfqButtons = document.querySelectorAll('.open-rfq-btn');
const closeModalBtns = document.querySelectorAll('.close-modal');
const rfqFabricSelect = document.getElementById('rfqFabricSelect');
rfqButtons.forEach(btn => {
btn.addEventListener('click', (e) => {
e.preventDefault();
const fabricName = btn.getAttribute('data-fabric');
if (fabricName && rfqFabricSelect) {
rfqFabricSelect.value = fabricName;
}
if (rfqModal) {
rfqModal.classList.add('open');
}
});
});
const webmailModal = document.getElementById('webmailModal');
const webmailBtns = document.querySelectorAll('.open-webmail-btn');
webmailBtns.forEach(btn => {
btn.addEventListener('click', (e) => {
e.preventDefault();
if (webmailModal) {
webmailModal.classList.add('open');
}
});
});
closeModalBtns.forEach(btn => {
btn.addEventListener('click', () => {
document.querySelectorAll('.modal-backdrop').forEach(modal => {
modal.classList.remove('open');
});
});
});
document.querySelectorAll('.modal-backdrop').forEach(modal => {
modal.addEventListener('click', (e) => {
if (e.target === modal) {
modal.classList.remove('open');
}
});
});
const galleryItems = document.querySelectorAll('.gallery-card');
const lightboxModal = document.getElementById('lightboxModal');
const lightboxImg = document.getElementById('lightboxImg');
const lightboxCaption = document.getElementById('lightboxCaption');
galleryItems.forEach(item => {
item.addEventListener('click', () => {
const img = item.querySelector('img');
const caption = item.querySelector('.gallery-caption')?.textContent || '';
if (lightboxModal && lightboxImg && img) {
lightboxImg.src = img.src;
if (lightboxCaption) lightboxCaption.textContent = caption;
lightboxModal.classList.add('open');
}
});
});
const rfqForm = document.getElementById('rfqForm');
const contactForm = document.getElementById('contactForm');
const webmailForm = document.getElementById('webmailForm');
function showToast(message) {
const toast = document.getElementById('toast');
if (!toast) return;
toast.querySelector('.toast-text').textContent = message;
toast.classList.add('show');
setTimeout(() => {
toast.classList.remove('show');
}, 4500);
}
if (rfqForm) {
rfqForm.addEventListener('submit', (e) => {
e.preventDefault();
rfqModal?.classList.remove('open');
showToast('Thank you! Your quotation / swatch request has been sent to our merchandising team.');
rfqForm.reset();
});
}
if (contactForm) {
contactForm.addEventListener('submit', (e) => {
e.preventDefault();
showToast('Inquiry sent successfully! Our commercial director will contact you within 24 hours.');
contactForm.reset();
});
}
if (webmailForm) {
webmailForm.addEventListener('submit', (e) => {
e.preventDefault();
showToast('Connecting to Alibaba Webmail portal (cPanel/Roundcube)...');
setTimeout(() => {
window.open('https://alibabatextilebd.com/webmail', '_blank');
webmailModal?.classList.remove('open');
}, 1200);
});
}
const sections = document.querySelectorAll('section[id]');
function highlightNavOnScroll() {
const scrollY = window.pageYOffset || document.documentElement.scrollTop;
const windowHeight = window.innerHeight;
const documentHeight = document.documentElement.scrollHeight;
if (scrollY + windowHeight >= documentHeight - 60) {
document.querySelectorAll('.nav-link').forEach(l => l.classList.remove('active'));
const contactLink = document.querySelector('.nav-link[href*="contact"]');
if (contactLink) contactLink.classList.add('active');
return;
}
sections.forEach(current => {
const sectionHeight = current.offsetHeight;
const sectionTop = current.offsetTop - 140;
const sectionId = current.getAttribute('id');
const link = document.querySelector(`.nav-link[href*="${sectionId}"]`);
if (scrollY >= sectionTop && scrollY < sectionTop + sectionHeight) {
link?.classList.add('active');
} else {
link?.classList.remove('active');
}
});
}
let navTicking = false;
window.addEventListener('scroll', () => {
if (!navTicking) {
window.requestAnimationFrame(() => {
highlightNavOnScroll();
navTicking = false;
});
navTicking = true;
}
}, { passive: true });
highlightNavOnScroll();
});